insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-00000000000e', 'en', null, 'American Government & Civics', 'A first tour of how the U.S. government is built and how citizens take part — from the Constitution and federalism to rights, the three branches, elections, and the media. Structure adapted from OpenStax American Government 3e (CC BY 4.0).', null, 'foundations', 14, true, 'science', '{}')
