insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-00000000000e', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The U.S. Constitution divides power among three branches. This is called…","options":["federalism","separation of powers","judicial review","popular sovereignty"],"answer":1,"explanation":"Separating legislative, executive, and judicial power is ''separation of powers'' — see ''The three branches''."},{"prompt":"The division of power between the national government and the states is called…","options":["federalism","checks and balances","the rule of law","bicameralism"],"answer":0,"explanation":"Federalism is the layered national–state arrangement — see ''Federalism''."},{"prompt":"The first ten amendments to the Constitution are known as the…","options":["Articles of Confederation","Bill of Rights","Federalist Papers","Declaration of Independence"],"answer":1,"explanation":"The Bill of Rights (1791) lists core protections — see ''Civil liberties''."},{"prompt":"The power of courts to strike down laws that conflict with the Constitution is…","options":["veto power","judicial review","impeachment","filibuster"],"answer":1,"explanation":"Judicial review was established in Marbury v. Madison (1803) — see ''The three branches''."},{"prompt":"Congress is made up of which two chambers?","options":["House and Senate","Senate and Cabinet","House and Supreme Court","Assembly and Congress"],"answer":0,"explanation":"The bicameral legislature is the House of Representatives and the Senate — see ''The three branches''."},{"prompt":"In a U.S. presidential election, the president is formally chosen by the…","options":["popular vote total","Electoral College","Supreme Court","Senate"],"answer":1,"explanation":"Electors, allocated by state, cast the formal votes — see ''Elections and voting''."},{"prompt":"Freedom of speech, religion, and the press are protected mainly by the…","options":["Tenth Amendment","First Amendment","Article II","Fourteenth Amendment"],"answer":1,"explanation":"The First Amendment covers these liberties — see ''Civil liberties and civil rights''."},{"prompt":"Which document created the U.S. government BEFORE the current Constitution?","options":["The Federalist Papers","The Articles of Confederation","The Emancipation Proclamation","The Magna Carta"],"answer":1,"explanation":"The Articles of Confederation (1781) preceded the 1787 Constitution — see ''Foundations''."}]}'::jsonb, null, 10),
  (2, 'Foundations and the Constitution', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why the Constitution replaced the Articles of Confederation and name its core design principles. Warm-up: from the diagnostic, which document governed the United States *before* the Constitution?"},{"heading":"The idea","text":"After independence, the *Articles of Confederation* created a weak national government that could not tax reliably or regulate trade between states. In 1787, delegates wrote a new *Constitution* built on a few load-bearing ideas: *popular sovereignty* (government''s authority comes from the people), *separation of powers* (splitting government into three branches), *checks and balances* (each branch can limit the others), and *federalism* (power shared between national and state governments). The document can be changed only through a deliberate *amendment* process, which keeps it stable but adaptable."},{"heading":"Reasoning from the document","text":"The Constitution opens, ''We the People… do ordain and establish this Constitution.'' That phrase locates authority in citizens, not a monarch. Article I creates Congress, Article II the presidency, Article III the courts — the ordering itself reflects the framers'' emphasis on the legislature. Because ratification was contested, supporters published *The Federalist Papers* to argue that a stronger union would still protect liberty."},{"heading":"Your turn","text":"Match each principle to its description: (1) popular sovereignty, (2) separation of powers, (3) checks and balances, (4) federalism. Options: (a) power split between nation and states, (b) authority comes from the people, (c) government divided into three branches, (d) each branch can restrain the others. Answers: 1-b, 2-c, 3-d, 4-a."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating ''separation of powers'' and ''checks and balances'' as the same thing — the first divides the branches, the second lets them limit one another. Mistake: assuming the Constitution can never change (it has been amended 27 times). Exit: (a) What replaced the Articles of Confederation? (b) Name the principle that authority comes from the people. Answers: the Constitution; popular sovereignty."}]}'::jsonb, '''Republic'' = government by elected representatives, not direct rule by the crowd.', 13),
  (3, 'Federalism: sharing power with the states', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe how the Constitution divides authority between the national and state governments. Warm-up: what do we call the sharing of power between a central government and regional governments?"},{"heading":"The idea","text":"*Federalism* gives the national government certain *enumerated powers* (listed in the Constitution, such as coining money and regulating interstate commerce) while the Tenth Amendment leaves *reserved powers* to the states (such as running elections and public schools). Some *concurrent powers*, like the power to tax, are shared. The *supremacy clause* in Article VI says that when valid national law and state law truly conflict, national law prevails. Over time, courts and Congress have adjusted this balance rather than fixing it once and for all."},{"heading":"Reasoning from the document","text":"The Tenth Amendment states that powers not delegated to the national government ''are reserved to the States respectively, or to the people.'' This is why driver''s licenses, marriage records, and local policing are handled by states, while passports and national defense are federal. Grants of money from the national government to the states are a common tool that shapes state policy without directly commanding it."},{"heading":"Your turn","text":"Label each as national (N), state (S), or concurrent (C): (1) coining money, (2) issuing driver''s licenses, (3) collecting taxes, (4) declaring war, (5) running public schools. Answers: 1-N, 2-S, 3-C, 4-N, 5-S."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking the national government can override any state decision — the supremacy clause applies only when there is a genuine conflict with valid federal law. Mistake: assuming states have no independent authority. Exit: (a) Which amendment reserves powers to the states? (b) Give one power shared by both levels. Answers: the Tenth Amendment; taxation (concurrent)."}]}'::jsonb, 'Enumerated = listed for the nation; reserved = left to the states.', 12),
  (4, 'Civil liberties and civil rights', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Distinguish civil liberties from civil rights and identify where each is protected. Warm-up: which set of amendments is called the Bill of Rights?"},{"heading":"The idea","text":"*Civil liberties* are protections *from* government interference — such as free speech, free exercise of religion, and due process — many listed in the *Bill of Rights* (the first ten amendments). *Civil rights* concern equal treatment under the law and protection from discrimination, anchored largely in the *Fourteenth Amendment''s* equal protection clause. Neither is unlimited: courts weigh individual freedom against other public interests, and the meaning of these protections has been worked out case by case."},{"heading":"Reasoning from the document","text":"The First Amendment begins, ''Congress shall make no law… abridging the freedom of speech.'' That is a *liberty* — a limit on government action. The Fourteenth Amendment''s promise that no state shall ''deny to any person… the equal protection of the laws'' is the foundation of *civil rights*, and courts have used it to strike down laws that treated groups of citizens unequally. The distinction matters: a free-speech dispute and a discrimination dispute are argued on different constitutional grounds."},{"heading":"Your turn","text":"Classify each as a civil liberty (L) or a civil right (R): (1) practicing your religion freely, (2) equal access to public services regardless of race, (3) refusing to answer police without a lawyer, (4) equal treatment in voting rules, (5) publishing a newspaper critical of officials. Answers: 1-L, 2-R, 3-L, 4-R, 5-L."},{"heading":"Common mistakes & exit ticket","text":"Mistake: using ''liberties'' and ''rights'' interchangeably — liberties limit what government may do to you; rights guarantee equal treatment. Mistake: thinking any freedom is absolute (courts balance them). Exit: (a) The Bill of Rights is which amendments? (b) Which amendment anchors equal protection? Answers: the first ten; the Fourteenth."}]}'::jsonb, 'Liberties = freedoms FROM government; rights = protection from unequal treatment.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The Articles of Confederation were replaced because they created a national government that was…","options":["too powerful","too weak","a monarchy","a direct democracy"],"answer":1,"explanation":"It could not tax reliably or regulate interstate trade."},{"prompt":"''We the People'' in the Preamble expresses the principle of…","options":["federalism","popular sovereignty","judicial review","bicameralism"],"answer":1,"explanation":"Authority comes from the people."},{"prompt":"Powers not given to the national government are reserved to the states by the…","options":["First Amendment","Tenth Amendment","supremacy clause","commerce clause"],"answer":1,"explanation":"The Tenth Amendment reserves powers to the states or the people."},{"prompt":"Taxation is an example of a … power.","options":["enumerated (national only)","reserved (state only)","concurrent (shared)","judicial"],"answer":2,"explanation":"Both national and state governments can tax."},{"prompt":"Free speech and free exercise of religion are best described as…","options":["civil rights","civil liberties","reserved powers","concurrent powers"],"answer":1,"explanation":"Liberties are protections from government interference."},{"prompt":"The Fourteenth Amendment''s equal protection clause is the main basis for…","options":["civil liberties","civil rights","the veto","federal grants"],"answer":1,"explanation":"Equal protection anchors civil-rights law."}]}'::jsonb, null, 8),
  (6, 'The three branches of government', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the three branches, their core jobs, and how they check one another. Warm-up: which branch is made up of the House and the Senate?"},{"heading":"The idea","text":"The *legislative branch* (Congress: the House of Representatives and the Senate) writes laws and controls federal spending. The *executive branch* (the president and federal agencies) carries out and enforces laws. The *judicial branch* (the Supreme Court and lower federal courts) interprets laws and can use *judicial review* to decide whether a law is constitutional. *Checks and balances* connect them: Congress passes a bill, the president can *veto* it, Congress can override a veto, and the courts can rule on whether the law is constitutional."},{"heading":"Worked examples","text":"Example 1: Congress passes a budget → the president signs or vetoes it → if vetoed, Congress may override with a two-thirds vote in each chamber. Example 2: A law is challenged in court → judges apply *judicial review*, established in Marbury v. Madison (1803), to decide if it conflicts with the Constitution. Example 3: The president nominates a judge → the Senate confirms or rejects the nominee — an executive action checked by the legislature."},{"heading":"Your turn","text":"Match the action to its branch — legislative (L), executive (E), or judicial (J): (1) vetoing a bill, (2) declaring a law unconstitutional, (3) writing and passing a bill, (4) enforcing federal law through agencies, (5) confirming a judicial nominee, (6) interpreting what a statute means. Answers: 1-E, 2-J, 3-L, 4-E, 5-L, 6-J."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking the president ''makes'' laws — the president can sign, veto, or enforce them, but Congress writes them. Mistake: assuming the Supreme Court enforces its own rulings (it relies on the other branches). Exit: (a) Which branch interprets laws? (b) What is a veto override vote fraction in each chamber? Answers: the judicial branch; two-thirds."}]}'::jsonb, 'Legislative makes law, executive enforces it, judicial interprets it.', 14),
  (7, 'Elections, voting, and political parties', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how U.S. elections are structured and the role political parties play. Warm-up: what body formally elects the president after citizens vote?"},{"heading":"The idea","text":"In U.S. elections, most citizens age 18 and older may *vote*. Candidates are usually chosen in *primary* elections or caucuses, then compete in the *general* election. For the presidency, voters in each state help determine that state''s *electors*, and the *Electoral College* casts the formal votes. *Political parties* are organizations that recruit candidates, organize voters, and structure debate; the United States has long had two major parties alongside smaller ones. Parties help voters make sense of choices, but the system is designed so that power still depends on winning elections."},{"heading":"Reasoning from the process","text":"Consider a presidential year: in the spring, parties hold primaries to pick nominees; in November, citizens vote; each state (with two exceptions that split votes) awards its electors to the statewide winner; in December the electors formally vote. Because electoral votes are allocated by state, campaigns focus effort where the outcome is close. This is a neutral description of the mechanics — the same rules apply to every party."},{"heading":"Your turn","text":"Put these steps in order for a presidential election: (a) general election in November, (b) primaries and caucuses, (c) Electoral College casts formal votes, (d) parties nominate candidates. Also answer: (e) what is the minimum voting age nationally? Answers: order is b → d → a → c; minimum voting age is 18."},{"heading":"Common mistakes & exit ticket","text":"Mistake: believing the national popular-vote total legally decides the presidency — the Electoral College casts the formal votes. Mistake: confusing a primary (choosing a party''s nominee) with the general election (choosing among nominees). Exit: (a) What is the purpose of a primary election? (b) Who casts the formal votes for president? Answers: to select a party''s nominee; the electors of the Electoral College."}]}'::jsonb, 'Primary = choose a party''s nominee; general = choose among nominees.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"federalism","translation":"the sharing of power between a national government and state governments","example":"Under federalism, states run elections while the nation handles defense."},{"term":"separation of powers","translation":"dividing government into legislative, executive, and judicial branches","example":"Separation of powers keeps any one branch from doing everything."},{"term":"checks and balances","translation":"the ways each branch can limit the actions of the others","example":"A presidential veto is one of the checks and balances."},{"term":"civil liberties","translation":"protections from government interference, such as free speech and religion","example":"The First Amendment protects core civil liberties."},{"term":"judicial review","translation":"the power of courts to decide whether a law is constitutional","example":"Judicial review was established in Marbury v. Madison."},{"term":"Electoral College","translation":"the body of electors that formally chooses the U.S. president","example":"Each state''s electors make up the Electoral College."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"The legislative branch''s core job is to…","options":["interpret laws","enforce laws","write laws","appoint judges"],"answer":2,"explanation":"Congress writes laws and controls spending."},{"prompt":"Judicial review lets courts…","options":["veto bills","decide if a law is constitutional","collect taxes","declare war"],"answer":1,"explanation":"Established in Marbury v. Madison (1803)."},{"prompt":"A presidential veto can be overridden by…","options":["the Supreme Court","a two-thirds vote in each chamber of Congress","a national referendum","the Cabinet"],"answer":1,"explanation":"Two-thirds of both the House and Senate."},{"prompt":"A primary election is used to…","options":["choose a party''s nominee","count electoral votes","confirm judges","amend the Constitution"],"answer":0,"explanation":"Primaries select each party''s candidate."},{"prompt":"The president is formally elected by the…","options":["popular vote total","Electoral College","House of Representatives","state governors"],"answer":1,"explanation":"Electors cast the formal votes."},{"prompt":"Which branch enforces federal laws through its agencies?","options":["legislative","executive","judicial","state"],"answer":1,"explanation":"The executive branch carries out and enforces laws."}]}'::jsonb, null, 8),
  (10, 'Applied project: analyze a civic issue', 'writing', '{"sections":[{"heading":"The task","text":"Choose a current civic issue you care about (for example, how elections are administered, a free-speech question, or a national-versus-state policy dispute). Analyze it using constitutional principles from this course. You are not arguing for a political side — you are explaining how the constitutional framework applies to the issue."},{"heading":"Milestones","text":"1) State the issue neutrally in one or two sentences. 2) Identify which constitutional principles are involved (for example, federalism, separation of powers, civil liberties, or civil rights) and which branch or level of government has authority. 3) Present the strongest reasoning on more than one side, keeping the tone fair to each. 4) Explain how the Constitution''s design (checks and balances, amendment process, or courts) is meant to resolve disagreements like this one."},{"heading":"Self-check rubric","text":"✔ The issue is described neutrally, without loaded language. ✔ You correctly named at least one relevant constitutional principle. ✔ You identified the responsible branch or level of government. ✔ You represented more than one perspective fairly and pointed to a constitutional process (courts, elections, or amendment) for resolving it. If all four are true, you''ve analyzed the issue like a civics scholar."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-00000000000e' and l.position = v.pos
);
